-- ============================================================================
-- V1 — Schéma initial (PostgreSQL)
--
-- Source : docs/SI jee project.md
--   §2 Entités, §3 Associations (cardinalités), §4 MLD, §7 Règles de gestion.
--
-- Conventions (AGENTS.md) :
--   * Commentaires en français, identifiants SQL en anglais.
--   * Clés techniques en bigint GENERATED BY DEFAULT AS IDENTITY.
--   * Contraintes nommées pk_ / fk_ / uq_ / ck_ pour faciliter les diagnostics.
--   * ETUDIANT et ENSEIGNANT sont des spécialisations de UTILISATEUR : elles
--     partagent la clé primaire de la table mère (relation 1-0..1).
--   * Le modèle ne stocke ni mot de passe (OAuth + 2FA), ni nom de classe
--     dérivé (niveau + parcours), ni emploi du temps (calculé).
--
-- Correspondance MCD -> tables :
--   UTILISATEUR -> app_user          CRENEAU    -> time_slot
--   ETUDIANT    -> student           SALLE      -> room
--   ENSEIGNANT  -> teacher           ABSENCE    -> absence
--   CLASSE      -> school_class      PERIODE    -> period
--   UE          -> course_unit       ENSEIGNER  -> teaching_assignment
--   ECUE        -> course_element    INSCRIRE   -> enrollment
--                                    NOTER      -> grade
-- ============================================================================

-- ----------------------------------------------------------------------------
-- Utilisateurs et spécialisations
-- ----------------------------------------------------------------------------

CREATE TABLE app_user (
    id         bigint GENERATED BY DEFAULT AS IDENTITY,
    email      varchar(320) NOT NULL,
    last_name  varchar(100) NOT NULL,
    first_name varchar(100) NOT NULL,
    role       varchar(20)  NOT NULL,
    active     boolean      NOT NULL DEFAULT true,
    CONSTRAINT pk_app_user PRIMARY KEY (id),
    CONSTRAINT uq_app_user_email UNIQUE (email),
    CONSTRAINT ck_app_user_role CHECK (role IN ('STUDENT', 'TEACHER', 'ADMIN'))
);

CREATE TABLE student (
    id                  bigint      NOT NULL,
    registration_number varchar(30) NOT NULL,
    CONSTRAINT pk_student PRIMARY KEY (id),
    CONSTRAINT uq_student_registration_number UNIQUE (registration_number),
    CONSTRAINT fk_student_app_user FOREIGN KEY (id)
        REFERENCES app_user (id) ON DELETE CASCADE
);

CREATE TABLE teacher (
    id            bigint      NOT NULL,
    academic_rank varchar(50) NOT NULL,
    CONSTRAINT pk_teacher PRIMARY KEY (id),
    CONSTRAINT fk_teacher_app_user FOREIGN KEY (id)
        REFERENCES app_user (id) ON DELETE CASCADE
);

-- ----------------------------------------------------------------------------
-- Structure pédagogique : school_class > course_unit > course_element
-- ----------------------------------------------------------------------------

CREATE TABLE school_class (
    id    bigint       GENERATED BY DEFAULT AS IDENTITY,
    level varchar(50)  NOT NULL,
    track varchar(100) NOT NULL,
    CONSTRAINT pk_school_class PRIMARY KEY (id)
);

CREATE TABLE course_unit (
    id        bigint       GENERATED BY DEFAULT AS IDENTITY,
    class_id  bigint       NOT NULL,
    code      varchar(20)  NOT NULL,
    title     varchar(200) NOT NULL,
    credits   integer      NOT NULL,
    term      integer      NOT NULL,
    CONSTRAINT pk_course_unit PRIMARY KEY (id),
    CONSTRAINT fk_course_unit_school_class FOREIGN KEY (class_id)
        REFERENCES school_class (id) ON DELETE CASCADE,
    CONSTRAINT ck_course_unit_credits CHECK (credits > 0),
    CONSTRAINT ck_course_unit_term CHECK (term BETWEEN 1 AND 3)
);

CREATE TABLE course_element (
    id              bigint        GENERATED BY DEFAULT AS IDENTITY,
    course_unit_id  bigint        NOT NULL,
    code            varchar(20)   NOT NULL,
    title           varchar(200)  NOT NULL,
    hours           integer       NOT NULL,
    coefficient     numeric(4, 2) NOT NULL,
    CONSTRAINT pk_course_element PRIMARY KEY (id),
    CONSTRAINT fk_course_element_course_unit FOREIGN KEY (course_unit_id)
        REFERENCES course_unit (id) ON DELETE CASCADE,
    CONSTRAINT ck_course_element_hours CHECK (hours > 0),
    CONSTRAINT ck_course_element_coefficient CHECK (coefficient > 0)
);

-- ----------------------------------------------------------------------------
-- Planification : teaching_assignment, time_slot, room, absence, period
-- ----------------------------------------------------------------------------

CREATE TABLE room (
    id       bigint       GENERATED BY DEFAULT AS IDENTITY,
    name     varchar(100) NOT NULL,
    capacity integer      NOT NULL,
    CONSTRAINT pk_room PRIMARY KEY (id),
    CONSTRAINT uq_room_name UNIQUE (name),
    CONSTRAINT ck_room_capacity CHECK (capacity > 0)
);

CREATE TABLE period (
    id            bigint     GENERATED BY DEFAULT AS IDENTITY,
    academic_year varchar(9) NOT NULL,
    term          integer    NOT NULL,
    CONSTRAINT pk_period PRIMARY KEY (id),
    CONSTRAINT uq_period UNIQUE (academic_year, term),
    CONSTRAINT ck_period_academic_year CHECK (academic_year ~ '^[0-9]{4}-[0-9]{4}$'),
    CONSTRAINT ck_period_term CHECK (term BETWEEN 1 AND 3)
);

-- Association n-n ENSEIGNANT – ECUE (CM et TD peuvent être assurés par
-- des enseignants différents).
CREATE TABLE teaching_assignment (
    teacher_id        bigint NOT NULL,
    course_element_id bigint NOT NULL,
    CONSTRAINT pk_teaching_assignment PRIMARY KEY (teacher_id, course_element_id),
    CONSTRAINT uq_teaching_assignment_element_teacher UNIQUE (course_element_id, teacher_id),
    CONSTRAINT fk_teaching_assignment_teacher FOREIGN KEY (teacher_id)
        REFERENCES teacher (id) ON DELETE CASCADE,
    CONSTRAINT fk_teaching_assignment_course_element FOREIGN KEY (course_element_id)
        REFERENCES course_element (id) ON DELETE CASCADE
);

-- Un créneau planifié (cours, TD, TP, examen ou rattrapage).
CREATE TABLE time_slot (
    id                bigint      GENERATED BY DEFAULT AS IDENTITY,
    course_element_id bigint      NOT NULL,
    teacher_id        bigint      NOT NULL,
    room_id           bigint      NOT NULL,
    day               date        NOT NULL,
    start_time        time        NOT NULL,
    end_time          time        NOT NULL,
    type              varchar(20) NOT NULL,
    results_published boolean     NOT NULL DEFAULT false,
    CONSTRAINT pk_time_slot PRIMARY KEY (id),
    -- Règle §7.4 : l'enseignant du créneau doit être lié à son ECUE.
    CONSTRAINT fk_time_slot_teaching_assignment FOREIGN KEY (course_element_id, teacher_id)
        REFERENCES teaching_assignment (course_element_id, teacher_id),
    CONSTRAINT fk_time_slot_room FOREIGN KEY (room_id)
        REFERENCES room (id),
    CONSTRAINT ck_time_slot_type CHECK (type IN ('COURSE', 'TUTORIAL', 'PRACTICAL', 'EXAM', 'RETAKE')),
    CONSTRAINT ck_time_slot_hours CHECK (end_time > start_time)
);

CREATE TABLE absence (
    id         bigint GENERATED BY DEFAULT AS IDENTITY,
    teacher_id bigint NOT NULL,
    start_date date   NOT NULL,
    end_date   date   NOT NULL,
    reason     text,
    CONSTRAINT pk_absence PRIMARY KEY (id),
    CONSTRAINT fk_absence_teacher FOREIGN KEY (teacher_id)
        REFERENCES teacher (id) ON DELETE CASCADE,
    CONSTRAINT ck_absence_dates CHECK (end_date >= start_date)
);

-- ----------------------------------------------------------------------------
-- Inscriptions et notes
-- ----------------------------------------------------------------------------

-- Association ternaire ETUDIANT – CLASSE – PERIODE, qui conserve
-- l'historique des inscriptions et porte le statut de décision.
CREATE TABLE enrollment (
    student_id bigint      NOT NULL,
    class_id   bigint      NOT NULL,
    period_id  bigint      NOT NULL,
    status     varchar(20) NOT NULL DEFAULT 'PENDING',
    CONSTRAINT pk_enrollment PRIMARY KEY (student_id, class_id, period_id),
    CONSTRAINT fk_enrollment_student FOREIGN KEY (student_id)
        REFERENCES student (id) ON DELETE CASCADE,
    CONSTRAINT fk_enrollment_school_class FOREIGN KEY (class_id)
        REFERENCES school_class (id),
    CONSTRAINT fk_enrollment_period FOREIGN KEY (period_id)
        REFERENCES period (id),
    CONSTRAINT ck_enrollment_status CHECK (status IN ('PENDING', 'VALIDATED'))
);

CREATE TABLE grade (
    student_id   bigint        NOT NULL,
    time_slot_id bigint        NOT NULL,
    score        numeric(4, 2) NOT NULL,
    CONSTRAINT pk_grade PRIMARY KEY (student_id, time_slot_id),
    CONSTRAINT fk_grade_student FOREIGN KEY (student_id)
        REFERENCES student (id) ON DELETE CASCADE,
    CONSTRAINT fk_grade_time_slot FOREIGN KEY (time_slot_id)
        REFERENCES time_slot (id) ON DELETE CASCADE,
    CONSTRAINT ck_grade_score CHECK (score BETWEEN 0 AND 20)
);

-- ----------------------------------------------------------------------------
-- Index sur les clés étrangères et les colonnes de consultation
-- ----------------------------------------------------------------------------

CREATE INDEX ix_course_unit_class ON course_unit (class_id);
CREATE INDEX ix_course_element_course_unit ON course_element (course_unit_id);
CREATE INDEX ix_teaching_assignment_course_element ON teaching_assignment (course_element_id);
CREATE INDEX ix_time_slot_course_element ON time_slot (course_element_id);
CREATE INDEX ix_time_slot_room_day ON time_slot (room_id, day);
CREATE INDEX ix_time_slot_teacher_day ON time_slot (teacher_id, day);
CREATE INDEX ix_absence_teacher ON absence (teacher_id, start_date, end_date);
CREATE INDEX ix_enrollment_class ON enrollment (class_id);
CREATE INDEX ix_enrollment_period ON enrollment (period_id);
CREATE INDEX ix_grade_time_slot ON grade (time_slot_id);

-- ============================================================================
-- Règles de gestion relevant de l'application (docs §7) :
--
-- 1. NOTER n'est autorisé que si CRENEAU.type vaut EXAMEN ou RATTRAPAGE et si
--    l'étudiant est inscrit dans la classe de l'ECUE.
-- 2. Deux CRENEAUX ne peuvent pas se chevaucher pour une même salle, un même
--    enseignant ou une même classe (à vérifier via ECUE → UE → CLASSE).
-- 3. Un CRENEAU ne peut pas être réservé si l'enseignant est absent sur cette
--    date.
--
-- La règle 4 (enseignant lié à l'ECUE) est garantie par
-- fk_time_slot_teaching_assignment ci-dessus.
-- ============================================================================